/** Returns the Latvian policy for locale "lv", otherwise the English original. */
export function getPolicy(key: string, locale: string): PolicyContent {
  const english = POLICIES[key];
  if (locale === "lv") return POLICIES_LV[key] ?? english;
  return english;
}
